package tn.esprit.partnerintelligence.service;import org.springframework.stereotype.Service;import tn.esprit.partnerintelligence.entity.RecommendationItem;@Service public class RecommendationEngineService{ public RecommendationItem build(Long partnerId,double health){ RecommendationItem i=new RecommendationItem(); i.setPartnerId(partnerId); i.setPriorityRank(1); i.setConfidence(0.8); i.setActionTitle(health<70?"Launch retention voucher":"Scale high-conversion channel"); i.setRationale("Generated from partner KPI trend and deal health factors."); return i; }}